// Keyboard input. Tracks pressed keys and exposes intent flags per frame.
// Deliberately framework-free and side-effect free beyond key state.

export class InputManager {
  constructor(target = window) {
    this.target = target;
    this.keys = new Set();
    this._prev = new Set();
    this._onKeyDown = (e) => this._handleKey(e, true);
    this._onKeyUp = (e) => this._handleKey(e, false);
    this._bound = false;
  }

  attach() {
    if (this._bound) return;
    this.target.addEventListener('keydown', this._onKeyDown);
    this.target.addEventListener('keyup', this._onKeyUp);
    this._bound = true;
  }

  detach() {
    if (!this._bound) return;
    this.target.removeEventListener('keydown', this._onKeyDown);
    this.target.removeEventListener('keyup', this._onKeyUp);
    this._bound = false;
    this.keys.clear();
    this._prev.clear();
  }

  _handleKey(e, down) {
    const code = e.code;
    // Prevent page scroll on game keys.
    if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(code)) {
      e.preventDefault();
    }
    if (down) this.keys.add(code);
    else this.keys.delete(code);
  }

  isDown(code) {
    return this.keys.has(code);
  }

  /** True only on the frame a key goes down (edge-triggered). */
  justPressed(code) {
    return this.keys.has(code) && !this._prev.has(code);
  }

  /** Call once per frame after sampling to refresh edge state. */
  endFrame() {
    this._prev = new Set(this.keys);
  }

  /**
   * Sample current intents. Call once per frame.
   */
  sample() {
    const k = this.keys;
    return {
      thrust: k.has('KeyW') || k.has('ArrowUp'),
      reverse: k.has('KeyS') || k.has('ArrowDown'),
      turnLeft: k.has('KeyA') || k.has('ArrowLeft'),
      turnRight: k.has('KeyD') || k.has('ArrowRight'),
      rollLeft: k.has('KeyQ'),
      rollRight: k.has('KeyE'),
      boost: k.has('ShiftLeft') || k.has('ShiftRight'),
      tractor: k.has('Space'),
    };
  }
}

// The player's salvage ship: procedural mesh, engine glow, tractor beam,
// and the arcade flight model (inertia, drag, angular velocity, speed caps).

import * as THREE from 'three';
import { CONFIG } from '../config.js';
import {
  forwardFromOrientation, upFromOrientation, rightFromOrientation,
  addScaled, scale, length, clampLength,
} from '../utils/math.js';

export class PlayerShip {
  constructor(scene) {
    this.scene = scene;
    this.position = { x: 0, y: 0, z: 0 };
    this.velocity = { x: 0, y: 0, z: 0 };
    this.orientation = { yaw: 0, pitch: 0, roll: 0 };
    this.thrusting = false;
    this.boosting = false;
    this.tractorOn = false;

    this.group = new THREE.Group();
    this._buildMesh();
    scene.add(this.group);
  }

  _buildMesh() {
    const c = CONFIG.ship;
    const hullMat = new THREE.MeshStandardMaterial({ color: 0xd8e4f0, metalness: 0.7, roughness: 0.35 });
    const accentMat = new THREE.MeshStandardMaterial({ color: 0x2a6fb0, metalness: 0.6, roughness: 0.4 });
    const glowMat = new THREE.MeshBasicMaterial({ color: 0x66e0ff });

    // Fuselage: a stretched cone pointing -Z (forward).
    const body = new THREE.Mesh(new THREE.ConeGeometry(1.1, 4.2, 6), hullMat);
    body.rotation.x = -Math.PI / 2;
    this.group.add(body);

    // Wings.
    const wingGeo = new THREE.BoxGeometry(4.6, 0.18, 1.4);
    const wings = new THREE.Mesh(wingGeo, accentMat);
    wings.position.set(0, -0.2, 1.2);
    this.group.add(wings);

    // Cockpit dome.
    const dome = new THREE.Mesh(
      new THREE.SphereGeometry(0.55, 12, 10),
      new THREE.MeshStandardMaterial({ color: 0x88ddff, metalness: 0.2, roughness: 0.1, emissive: 0x224466 })
    );
    dome.position.set(0, 0.45, -0.4);
    this.group.add(dome);

    // Engine nozzles + glow discs (scale with thrust).
    this.engineGlow = new THREE.Group();
    for (const x of [-0.9, 0.9]) {
      const nozzle = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.42, 0.7, 10), accentMat);
      nozzle.rotation.x = Math.PI / 2;
      nozzle.position.set(x, 0, 2.3);
      this.group.add(nozzle);

      const glow = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.34, 0.9, 10), glowMat);
      glow.rotation.x = Math.PI / 2;
      glow.position.set(x, 0, 2.9);
      glow.material = glowMat.clone();
      glow.material.transparent = true;
      glow.material.opacity = 0;
      this.engineGlow.add(glow);
    }
    this.group.add(this.engineGlow);

    // Tractor beam: cone pointing forward, hidden until active.
    const beamGeo = new THREE.ConeGeometry(3.2, 14, 16, 1, true);
    beamGeo.translate(0, -7, 0); // apex at origin, opening forward
    const beamMat = new THREE.MeshBasicMaterial({
      color: 0x66ffcc, transparent: true, opacity: 0.22,
      side: THREE.DoubleSide, depthWrite: false,
    });
    this.beam = new THREE.Mesh(beamGeo, beamMat);
    this.beam.rotation.x = Math.PI / 2; // cone axis (local Y) -> -Z: opens toward the nose
    this.beam.position.z = -1.5;
    this.beam.visible = false;
    this.group.add(this.beam);

    this.group.scale.setScalar(c.radius / 2.1);
  }

  /**
   * Integrate flight. `input` is the InputManager.sample() result,
   * `extraAccel` is gravity/boundary acceleration, `thrustAllowed` gates
   * thrust when fuel is empty.
   */
  update(dt, input, extraAccel, thrustAllowed) {
    const c = CONFIG.ship;

    // --- Angular controls (angular velocity applied directly) ---
    const turn = c.turnSpeed * dt;
    if (input.turnLeft) this.orientation.yaw += turn;
    if (input.turnRight) this.orientation.yaw -= turn;
    if (input.rollLeft) this.orientation.roll += c.rollSpeed * dt;
    if (input.rollRight) this.orientation.roll -= c.rollSpeed * dt;

    // --- Linear thrust ---
    const forward = forwardFromOrientation(this.orientation);
    const boosting = input.boost && thrustAllowed;
    this.boosting = boosting;
    const power = c.thrust * (boosting ? c.boostMultiplier : 1);

    this.thrusting = (input.thrust || input.reverse) && thrustAllowed;
    if (input.thrust && thrustAllowed) {
      this.velocity = addScaled(this.velocity, forward, power * dt);
    } else if (input.reverse && thrustAllowed) {
      this.velocity = addScaled(this.velocity, forward, -c.reverseThrust * dt);
    }

    // Gravity + boundary.
    this.velocity = addScaled(this.velocity, extraAccel, dt);

    // Drag.
    const dragFactor = Math.exp(-c.drag * dt);
    this.velocity = scale(this.velocity, dragFactor);

    // Speed cap (boost gets a higher ceiling).
    const maxSpeed = boosting ? c.boostMaxSpeed : c.maxSpeed;
    this.velocity = clampLength(this.velocity, maxSpeed);

    // Integrate position.
    this.position = {
      x: this.position.x + this.velocity.x * dt,
      y: this.position.y + this.velocity.y * dt,
      z: this.position.z + this.velocity.z * dt,
    };
  }

  get speed() {
    return length(this.velocity);
  }

  get forward() {
    return forwardFromOrientation(this.orientation);
  }

  /** Sync the Three.js group with the simulated state. */
  syncVisuals(dt) {
    this.group.position.set(this.position.x, this.position.y, this.position.z);
    this.group.rotation.set(this.orientation.pitch, this.orientation.yaw, this.orientation.roll, 'YXZ');

    // Engine glow intensity follows thrust.
    const target = this.thrusting ? (this.boosting ? 0.95 : 0.55) : 0.08;
    for (const child of this.engineGlow.children) {
      child.material.opacity = THREE.MathUtils.lerp(child.material.opacity, target, 1 - Math.exp(-8 * dt));
      const s = 0.7 + target * 0.9;
      child.scale.set(1, s, 1);
    }

    // Tractor beam pulse.
    this.beam.visible = this.tractorOn;
    if (this.tractorOn) {
      const pulse = 0.16 + 0.1 * Math.sin(performance.now() * 0.012);
      this.beam.material.opacity = pulse;
      this.beam.scale.set(1, 1 + 0.04 * Math.sin(performance.now() * 0.02), 1);
    }
  }

  dispose() {
    this.scene.remove(this.group);
    this.group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        (Array.isArray(obj.material) ? obj.material : [obj.material]).forEach((m) => m.dispose());
      }
    });
  }
}

// Game orchestrator: owns the scene graph, the loop, and the wiring between
// input, state, entities, and systems. Kept free of pure math — that lives
// in the systems so it can be tested headlessly.

import * as THREE from 'three';
import { CONFIG } from '../config.js';
import { applyDifficulty, DIFFICULTIES } from './Difficulty.js';
import { InputManager } from '../input/InputManager.js';
import { PlayerShip } from '../entities/PlayerShip.js';
import { createPlanets } from '../entities/Planet.js';
import { Station } from '../entities/Station.js';
import { SpawnSystem } from '../systems/SpawnSystem.js';
import { EffectsSystem } from '../systems/EffectsSystem.js';
import { totalGravityAcceleration } from '../systems/GravitySystem.js';
import { spheresCollide, pointInSphere, pushOutOfSphere, bounceVelocity, tractorPullStep } from '../systems/CollisionSystem.js';
import {
  createGameState, MISSION_STATE, consumeFuel, applyDamage,
  updateDocking, tickMission, boundaryCorrection, applyImpulse,
  missionTimeRemaining, surgeMultiplier,
} from '../game/GameState.js';
import { findTriggeredMine } from './Mines.js';
import { AudioSystem } from '../systems/AudioSystem.js';
import { HUD } from '../ui/HUD.js';
import { summarizeStats } from './Stats.js';
import { updateRecords } from '../utils/storage.js';
import { forwardFromOrientation, upFromOrientation, rightFromOrientation, sub, scale, distance, length } from '../utils/math.js';

export class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x04060f);
    this.scene.fog = new THREE.Fog(0x04060f, 500, 1400);

    this.camera = new THREE.PerspectiveCamera(62, 1, 0.1, 3000);
    this._resize();
    window.addEventListener('resize', () => this._resize());

    // Lights.
    this.scene.add(new THREE.AmbientLight(0x334466, 0.9));
    const sun = new THREE.DirectionalLight(0xfff2dd, 1.6);
    sun.position.set(300, 200, 100);
    this.scene.add(sun);
    const rim = new THREE.DirectionalLight(0x4488ff, 0.5);
    rim.position.set(-200, -100, -300);
    this.scene.add(rim);

    this.input = new InputManager(window);
    this.input.attach();

    this.config = CONFIG; // active (difficulty-applied) config; replaced on start()
    this.difficulty = 'normal';

    this.planets = createPlanets(this.scene);
    this.station = new Station(this.scene);
    this.ship = new PlayerShip(this.scene);
    this.spawner = new SpawnSystem(this.scene);
    this.effects = new EffectsSystem(this.scene);
    this.hud = new HUD();
    this.audio = new AudioSystem({ storage: window.localStorage });

    this.state = createGameState();
    this.clock = new THREE.Clock();
    this.cameraShake = 0;
    this._camPos = new THREE.Vector3(0, 5, 13);
    this._endShown = false;
    this.paused = false;

    this.hud.showStart(this.difficulty);
    this._refreshDifficultyButtons();
    this._loop = this._loop.bind(this);
    requestAnimationFrame(this._loop);
  }

  _resize() {
    const w = this.canvas.clientWidth || window.innerWidth;
    const h = this.canvas.clientHeight || window.innerHeight;
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }

  /**
   * Select the mission difficulty (easy/normal/hard). Takes effect from the
   * next start(); also updates the start overlay's button states.
   */
  setDifficulty(name) {
    if (!DIFFICULTIES.includes(name)) return false;
    this.difficulty = name;
    this._refreshDifficultyButtons();
    return true;
  }

  _refreshDifficultyButtons() {
    const wrap = document.getElementById('difficulty-row');
    if (!wrap) return;
    for (const btn of wrap.querySelectorAll('button[data-difficulty]')) {
      btn.classList.toggle('selected', btn.dataset.difficulty === this.difficulty);
    }
  }

  start() {
    // start() is only reachable from a user gesture (button/Enter), so this
    // is the safe moment to create the WebAudio graph.
    this.audio.unlock();
    this.config = applyDifficulty(CONFIG, this.difficulty);
    this._resetMission();
    this._setPaused(false);
    this.state.state = MISSION_STATE.PLAYING;
    this.hud.hideStart();
    this.hud.hideEnd();
    this.hud.show();
  }

  restart() {
    if (this.state.state === MISSION_STATE.START) return;
    this.start();
  }

  /**
   * Abort the mission and return to the start screen (ESC). Works from
   * pause, mid-mission, and the results screen. Difficulty is preserved.
   */
  toMenu() {
    if (this.state.state === MISSION_STATE.START) return;
    this._resetMission();
    this._setPaused(false);
    this.hud.hideEnd();
    this.hud.showStart(this.difficulty);
    this.hud.hide();
    this._audioIdle(0.016);
  }

  /**
   * Pause/resume the mission (P). While paused the world is frozen and the
   * pause overlay is shown. Only valid during an active mission.
   */
  togglePause() {
    if (this.state.state !== MISSION_STATE.PLAYING) return;
    this._setPaused(!this.paused);
  }

  _setPaused(paused) {
    if (this.paused === paused) return;
    this.paused = paused;
    this.hud.showPause(paused);
    if (paused) {
      // Freeze the engine sounds; the graph keeps running so resuming is instant.
      this.audio.updateEngine({ thrusting: false, boosting: false, speedRatio: 0 });
      this.audio.setTractor(false);
    } else {
      // Reset the clock so the first unpaused frame has a normal dt.
      this.clock.getDelta();
    }
  }

  _resetMission() {
    // Clear spawned entities.
    this.spawner.dispose();
    this.spawner = new SpawnSystem(this.scene, this.config);
    this.state = createGameState(this.config);
    this.ship.position = { x: 0, y: 0, z: 40 };
    this.ship.velocity = { x: 0, y: 0, z: 0 };
    this.ship.orientation = { yaw: 0, pitch: 0, roll: 0 };
    this.ship.tractorOn = false;
    this._endShown = false;
    this.ship.syncVisuals(0.016);
    this.spawner.spawnInitial(this.ship.position);
    this.cameraShake = 0;
  }

  _loop() {
    requestAnimationFrame(this._loop);
    // Clamp dt so a background tab or hiccup can't tunnel the physics.
    const dt = Math.min(this.clock.getDelta(), this.config.loop.maxDelta);
    const input = this.input.sample();
    const restartPressed = this.input.justPressed('KeyR');
    const menuPressed = this.input.justPressed('Escape');
    if (this.input.justPressed('KeyM')) this.audio.toggleMute();
    if (this.input.justPressed('KeyP')) this.togglePause();

    const mode = this.state.state;
    if (mode === MISSION_STATE.PLAYING) {
      if (menuPressed) {
        this.toMenu();
      } else if (this.paused) {
        if (restartPressed) {
          this.restart();
        } else {
          // Frozen world behind the pause overlay; nothing advances.
          this.hud.update(this.state, 'PAUSED — P TO RESUME', null, { paused: true });
        }
      } else {
        this._updatePlaying(dt, input);
      }
    } else if (mode === MISSION_STATE.SUCCESS || mode === MISSION_STATE.FAILURE) {
      // End screen: world keeps drifting behind the overlay; R restarts, ESC menus.
      if (!this._endShown) {
        this._showEndScreen();
        this._endShown = true;
      }
      if (menuPressed) this.toMenu();
      else if (restartPressed) this.restart();
      for (const p of this.planets) p.update(dt);
      this.station.update(dt, 'outside');
      this.effects.update(dt);
      this._audioIdle(dt);
    } else {
      // Idle drift on the start menu: keep planets/station alive.
      for (const p of this.planets) p.update(dt);
      this.station.update(dt, 'outside');
      this.effects.update(dt);
      this._audioIdle(dt);
    }

    this._updateCamera(dt);
    this.renderer.render(this.scene, this.camera);
    this.input.endFrame();
  }

  _updatePlaying(dt, input) {
    const ship = this.ship;
    const state = this.state;

    // --- Fuel & thrust gating ---
    const thrusting = input.thrust || input.reverse;
    const boosting = input.boost && thrusting && state.fuel > 0;
    if (thrusting && state.fuel > 0) {
      consumeFuel(state, dt, boosting);
    }
    const thrustAllowed = state.fuel > 0;

    // --- Gravity + boundary ---
    const bodies = this.planets.map((p) => ({ position: p.position, gravity: p.gravity }));
    const gravity = totalGravityAcceleration(ship.position, bodies);
    const boundary = boundaryCorrection(ship.position);
    const extra = {
      x: gravity.x + boundary.x,
      y: gravity.y + boundary.y,
      z: gravity.z + boundary.z,
    };

    // --- Tractor beam (only pulls while there is cargo room) ---
    const beamActive = input.tractor && state.cargoItems.length < this.config.salvage.cargoCapacity;
    ship.tractorOn = beamActive;
    this._updateTractor(dt, beamActive);

    // --- Ship integration ---
    ship.update(dt, input, extra, thrustAllowed);

    // --- Collisions: planets ---
    const shipRadius = this.config.ship.radius;
    for (const planet of this.planets) {
      const minDist = planet.radius + shipRadius;
      if (spheresCollide(ship.position, shipRadius, planet.position, planet.radius)) {
        ship.position = pushOutOfSphere(ship.position, planet.position, minDist);
        const normal = scale(sub(planet.position, ship.position), -1);
        ship.velocity = bounceVelocity(ship.velocity, normal);
        this._onImpact(planet.position, 0xff8855, 18);
        if (applyDamage(state, this.config.ship.impactDamage)) this.audio.playDamage();
      }
    }

    // --- Collisions: station hub (the rings are decorative) ---
    const hubRadius = this.config.station.hubRadius;
    if (spheresCollide(ship.position, shipRadius, this.station.position, hubRadius)) {
      const minDist = hubRadius + shipRadius;
      ship.position = pushOutOfSphere(ship.position, this.station.position, minDist);
      const normal = scale(sub(this.station.position, ship.position), -1);
      ship.velocity = bounceVelocity(ship.velocity, normal);
      this._onImpact(ship.position, 0xff8855, 18);
      if (applyDamage(state, this.config.ship.impactDamage)) this.audio.playDamage();
    }

    // --- Collisions: hazards ---
    for (const hazard of this.spawner.hazards) {
      if (spheresCollide(ship.position, shipRadius, hazard.position, hazard.radius)) {
        const minDist = hazard.radius + shipRadius;
        ship.position = pushOutOfSphere(ship.position, hazard.position, minDist);
        const normal = scale(sub(hazard.position, ship.position), -1);
        ship.velocity = bounceVelocity(ship.velocity, normal);
        this._onImpact(hazard.position, 0xffaa44, 22);
        if (applyDamage(state, this.config.hazard.damage)) this.audio.playDamage();
      }
    }

    // --- Proximity mines: detonate when the ship enters the trigger radius ---
    const mine = findTriggeredMine(ship.position, this.spawner.mines);
    if (mine) {
      const dx = ship.position.x - mine.position.x;
      const dy = ship.position.y - mine.position.y;
      const dz = ship.position.z - mine.position.z;
      const d = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1e-6;
      const dir = { x: dx / d, y: dy / d, z: dz / d };
      this._detonateMine(mine);
      ship.velocity = applyImpulse(state, ship.velocity, dir, this.config.mine.knockback);
      if (applyDamage(state, this.config.mine.damage)) this.audio.playDamage();
      ship.position = pushOutOfSphere(ship.position, mine.position, mine.radius + shipRadius);
    }

    // --- Fuel canister pickup (iterate a copy: pickup mutates the array) ---
    for (const f of [...this.spawner.fuel]) {
      if (pointInSphere(ship.position, f.position, f.radius + shipRadius)) {
        state.fuel = Math.min(this.config.ship.maxFuel, state.fuel + this.config.fuelCanister.fuelRestore);
        this.effects.burst(f.position, 0x5dffa8, 16, 9);
        this.audio.playFuel();
        this.spawner.removeFuel(f);
        this.spawner.scheduleRespawn('fuel', state.time + this.config.fuelCanister.respawnDelay);
      }
    }

    // --- Salvage contact pickup (non-beamed) ---
    const cargoFull = state.cargoItems.length >= this.config.salvage.cargoCapacity;
    for (const s of [...this.spawner.salvage]) {
      if (!cargoFull && pointInSphere(ship.position, s.position, s.radius + shipRadius)) {
        this._collectSalvage(s);
      }
    }

    // --- Docking ---
    const dockResult = updateDocking(state, ship.position, ship.velocity, this.station, dt);
    if (dockResult === 'docked') {
      this.effects.burst(ship.position, 0x66ffcc, 26, 12);
      this._camShake(0.35);
      this.audio.playDock();
    } else if (dockResult === 'tooFast') {
      this._camShake(0.5);
      this.audio.playTooFast();
    }
    const shipSpeed = ship.speed;

    // --- Audio: engine hum, tractor whine, low-resource warnings ---
    this.audio.updateEngine({
      thrusting,
      boosting,
      speedRatio: Math.min(1, shipSpeed / this.config.ship.maxSpeed),
    });
    this.audio.setTractor(beamActive);
    const { fuelWarnRatio, hullWarnRatio } = this.config.limits;
    this.audio.updateWarnings(dt, {
      fuelLow: state.fuel / this.config.ship.maxFuel < fuelWarnRatio,
      hullLow: state.hull / this.config.ship.maxHull < hullWarnRatio,
    });

    const dockState = !state.inDockZone
      ? 'outside'
      : shipSpeed <= this.config.station.dockSpeedLimit
        ? 'safe'
        : 'tooFast';
    const dockSpeedLimit = this.config.station.dockSpeedLimit;

    // --- Spawner / effects / planets ---
    const surgeActive = surgeMultiplier(missionTimeRemaining(state), this.config) > 1;
    this.spawner.update(dt, state.time, ship.position, surgeActive);
    this.effects.update(dt);
    for (const p of this.planets) p.update(dt);
    this.station.update(dt, dockState);
    ship.syncVisuals(dt);

    // --- Mission tick (timer, win/lose, top speed) ---
    tickMission(state, dt, shipSpeed);

    // --- HUD ---
    let hint = '';
    if (state.inDockZone) {
      hint = length(ship.velocity) <= dockSpeedLimit
        ? 'DOCKING ZONE — SELLING CARGO'
        : 'DOCKING ZONE — SLOW DOWN';
    } else if (state.cargoItems.length >= this.config.salvage.cargoCapacity) {
      hint = 'CARGO HOLD FULL — DOCK TO SELL';
    } else if (input.tractor) {
      hint = 'TRACTOR BEAM ACTIVE';
    } else if (state.fuel / this.config.ship.maxFuel < this.config.limits.fuelWarnRatio) {
      hint = 'FUEL LOW — FIND A GREEN CANISTER';
    } else if (state.cargoItems.length > 0) {
      hint = `DELIVER ${state.cargoItems.length} CARGO AT THE STATION`;
    }
    const radarData = {
      shipPos: ship.position,
      orientation: ship.orientation,
      entities: [
        ...this.spawner.salvage.map((s) => ({ position: s.position, kind: 'salvage' })),
        ...this.spawner.fuel.map((f) => ({ position: f.position, kind: 'fuel' })),
        ...this.spawner.hazards.map((h) => ({ position: h.position, kind: 'hazard' })),
        ...this.spawner.mines.map((m) => ({ position: m.position, kind: 'mine' })),
      ],
      station: { position: this.station.position, visible: true },
      camera: {
        position: this.camera.position,
        forward: forwardFromOrientation(ship.orientation),
        right: rightFromOrientation(ship.orientation),
        up: upFromOrientation(ship.orientation),
      },
    };
    this.hud.update(state, hint, radarData, { surge: surgeActive, combo: state.combo });
  }

  _showEndScreen() {
    // Fold the finished run into the persistent records, then render stats.
    const { records, newCredits, newTime } = updateRecords(this.difficulty, {
      credits: this.state.credits,
      winTime: this.state.time,
      won: this.state.state === MISSION_STATE.SUCCESS,
    });
    const stats = summarizeStats(this.state, { difficulty: this.difficulty, records });
    this.hud.showEnd(this.state, { stats, newCredits, newTime });
  }

  _updateTractor(dt, on) {
    if (!on) return;
    const ship = this.ship;
    const c = this.config;
    for (const s of this.spawner.salvage) {
      const d = distance(ship.position, s.position);
      if (d > c.salvage.tractorRange) continue;
      // Pull the salvage toward the ship, clamped so it never overshoots.
      const pull = tractorPullStep(d, dt, c.salvage.tractorPull, s.radius + c.ship.radius);
      if (pull <= 0) continue;
      const dir = scale(sub(ship.position, s.position), 1 / (d || 1));
      s.position = {
        x: s.position.x + dir.x * pull,
        y: s.position.y + dir.y * pull,
        z: s.position.z + dir.z * pull,
      };
    }
  }

  _collectSalvage(entity) {
    this.state.cargoItems.push({ tier: entity.tier });
    this.state.salvageCollected += 1;
    this.effects.burst(entity.position, entity.color ?? 0x5dffa8, 20, 11);
    this.audio.playPickup();
    this.spawner.removeSalvage(entity);
    this.spawner.scheduleRespawn('salvage', this.state.time + this.config.salvage.respawnDelay);
  }

  _detonateMine(mine) {
    mine.detonated = true;
    this.effects.burst(mine.position, 0xff5533, 30, 16);
    this.spawner.removeMine(mine);
    this.spawner.scheduleRespawn('mine', this.state.time + this.config.mine.respawnDelay);
    this._camShake(0.7);
  }

  _onImpact(position, color, size) {
    this.effects.burst(position, color, size, 14);
    this._camShake(0.6);
  }

  /** Keep the audio graph alive but idle (no thrust, no beam) outside play. */
  _audioIdle(dt) {
    this.audio.updateEngine({ thrusting: false, boosting: false, speedRatio: 0 });
    this.audio.setTractor(false);
    this.audio.updateWarnings(dt, { fuelLow: false, hullLow: false });
  }

  _camShake(amount) {
    this.cameraShake = Math.max(this.cameraShake, amount);
  }

  _updateCamera(dt) {
    const c = this.config.camera;
    const ship = this.ship;
    const forward = forwardFromOrientation(ship.orientation);
    const up = upFromOrientation(ship.orientation);

    const desired = {
      x: ship.position.x - forward.x * c.distance + up.x * c.height,
      y: ship.position.y - forward.y * c.distance + up.y * c.height,
      z: ship.position.z - forward.z * c.distance + up.z * c.height,
    };
    const t = 1 - Math.exp(-c.follow * dt);
    this._camPos.x += (desired.x - this._camPos.x) * t;
    this._camPos.y += (desired.y - this._camPos.y) * t;
    this._camPos.z += (desired.z - this._camPos.z) * t;

    // Decaying collision shake.
    this.cameraShake = Math.max(0, this.cameraShake - c.shakeDecay * dt);
    const shake = this.cameraShake;
    this.camera.position.set(
      this._camPos.x + (Math.random() - 0.5) * shake,
      this._camPos.y + (Math.random() - 0.5) * shake,
      this._camPos.z + (Math.random() - 0.5) * shake
    );
    this.camera.lookAt(ship.position.x, ship.position.y, ship.position.z);
  }

  dispose() {
    this.input.detach();
    this.audio.dispose();
    this.ship.dispose();
    this.station.dispose(this.scene);
    this.spawner.dispose();
    this.effects.dispose();
    for (const p of this.planets) p.dispose(this.scene);
  }
}

// Deterministic collision helpers using bounding spheres. Pure functions.

import { distanceSq, lengthSq } from '../utils/math.js';

/**
 * Sphere-sphere overlap test.
 * @param {{x,y,z}} a position of sphere a
 * @param {number} ra radius of sphere a
 * @param {{x,y,z}} b position of sphere b
 * @param {number} rb radius of sphere b
 */
export function spheresCollide(a, ra, b, rb) {
  const r = ra + rb;
  return distanceSq(a, b) <= r * r;
}

/**
 * Point-in-sphere test (used for docking zones, canister pickup, etc.).
 */
export function pointInSphere(point, center, radius) {
  return distanceSq(point, center) <= radius * radius;
}

/**
 * Speed-squared check: is the ship moving slowly enough to dock safely?
 */
export function isBelowSpeed(velocity, maxSpeed) {
  return lengthSq(velocity) <= maxSpeed * maxSpeed;
}

/**
 * Push `pos` out of a sphere so it rests on the surface (used for
 * resolving planet/asteroid impacts).
 * @returns {{x,y,z}} corrected position
 */
export function pushOutOfSphere(pos, center, minDistance) {
  const dx = pos.x - center.x, dy = pos.y - center.y, dz = pos.z - center.z;
  const dSq = dx * dx + dy * dy + dz * dz;
  if (dSq >= minDistance * minDistance) return { x: pos.x, y: pos.y, z: pos.z };
  const d = Math.sqrt(dSq) || 1e-6;
  const s = minDistance / d;
  return { x: center.x + dx * s, y: center.y + dy * s, z: center.z + dz * s };
}

/**
 * Reflect velocity around a surface normal, keeping only the tangential
 * component (arcade-style bounce with damping).
 */
export function bounceVelocity(velocity, normal, damping = 0.4) {
  const dot = velocity.x * normal.x + velocity.y * normal.y + velocity.z * normal.z;
  if (dot >= 0) return { x: velocity.x, y: velocity.y, z: velocity.z }; // moving away
  return {
    x: (velocity.x - (1 + damping) * dot * normal.x),
    y: (velocity.y - (1 + damping) * dot * normal.y),
    z: (velocity.z - (1 + damping) * dot * normal.z),
  };
}

/**
 * Max distance a tractor beam may move an entity this step: the pull
 * impulse clamped so the entity never passes the ship (it stops just out of
 * contact range so the pickup check triggers next frame).
 *
 * @param {number} d current distance between ship and entity
 * @param {number} dt step in seconds
 * @param {number} pullSpeed tractor pull speed (u/s)
 * @param {number} minDistance contact distance (entity + ship radii)
 * @returns {number} distance to move (0 when already at contact)
 */
export function tractorPullStep(d, dt, pullSpeed, minDistance) {
  const wanted = pullSpeed * dt;
  return Math.max(0, Math.min(wanted, d - minDistance));
}

/**
 * Integrate a slowly drifting entity (salvage pod, fuel canister) and keep it
 * inside the play field: bounce it off protected spheres (planets, station)
 * and reflect it at the world boundary. Pure — returns new position/velocity.
 *
 * @param {{x,y,z}} position current position
 * @param {{x,y,z}} velocity current velocity
 * @param {number} dt step in seconds
 * @param {number} radius entity radius
 * @param {{position:{x,y,z}, radius:number}[]} bodies protected spheres
 * @param {number} bounds world half-extent (sphere around origin)
 * @returns {{position:{x,y,z}, velocity:{x,y,z}}}
 */
export function driftEntity(position, velocity, dt, radius, bodies, bounds) {
  let pos = {
    x: position.x + velocity.x * dt,
    y: position.y + velocity.y * dt,
    z: position.z + velocity.z * dt,
  };
  let vel = { x: velocity.x, y: velocity.y, z: velocity.z };

  for (const body of bodies) {
    const minDist = body.radius + radius;
    const dx = pos.x - body.position.x;
    const dy = pos.y - body.position.y;
    const dz = pos.z - body.position.z;
    const dSq = dx * dx + dy * dy + dz * dz;
    if (dSq >= minDist * minDist) continue;
    const d = Math.sqrt(dSq) || 1e-6;
    const nx = dx / d, ny = dy / d, nz = dz / d;
    // Rest on the surface.
    pos = {
      x: body.position.x + nx * minDist,
      y: body.position.y + ny * minDist,
      z: body.position.z + nz * minDist,
    };
    // Reflect the inward velocity component (elastic, no damping: drift speed
    // is low and damping would make pods stick to the surface).
    const dot = vel.x * nx + vel.y * ny + vel.z * nz;
    if (dot < 0) {
      vel = {
        x: vel.x - 2 * dot * nx,
        y: vel.y - 2 * dot * ny,
        z: vel.z - 2 * dot * nz,
      };
    }
  }

  // World boundary: reflect back inside.
  const b = bounds - radius;
  const dSq = pos.x * pos.x + pos.y * pos.y + pos.z * pos.z;
  if (dSq > b * b) {
    const d = Math.sqrt(dSq) || 1e-6;
    const nx = pos.x / d, ny = pos.y / d, nz = pos.z / d;
    const dot = vel.x * nx + vel.y * ny + vel.z * nz;
    if (dot > 0) {
      vel = {
        x: vel.x - 2 * dot * nx,
        y: vel.y - 2 * dot * ny,
        z: vel.z - 2 * dot * nz,
      };
    }
    pos = { x: pos.x * (b / d), y: pos.y * (b / d), z: pos.z * (b / d) };
  }

  return { position: pos, velocity: vel };
}

// Spawns and recycles salvage pods, fuel canisters, and asteroid hazards
// inside the play field, keeping counts stable and positions fair
// (never inside planets, never on top of the player or station).

import * as THREE from 'three';
import { CONFIG } from '../config.js';
import { Salvage } from '../entities/Salvage.js';
import { Hazard } from '../entities/Hazard.js';
import { Mine } from '../entities/Mine.js';
import { rollCargoTier } from '../game/Cargo.js';
import { distance } from '../utils/math.js';

export class SpawnSystem {
  constructor(scene, config = CONFIG) {
    this.scene = scene;
    this.config = config;
    this.salvage = [];
    this.fuel = [];
    this.hazards = [];
    this.mines = [];
    this.respawnQueue = []; // { type, readyAt }
    this.surgeActive = false; // late-mission market surge flag
  }

  // Protected spheres entities must never spawn inside (or drift into).
  _bodies() {
    const c = this.config;
    return [
      ...c.planets.map((p) => ({ position: p.position, radius: p.radius })),
      { position: c.station.position, radius: 0 },
    ];
  }

  _avoidList(playerPos, extraClear = 0) {
    const c = this.config;
    return [
      { position: playerPos, clear: c.spawn.playerClearance + extraClear },
      { position: c.station.position, clear: c.spawn.stationClearance },
      ...c.planets.map((p) => ({ position: p.position, clear: p.radius + c.spawn.planetClearance })),
    ];
  }

  _randomPoint(minR, maxR, avoid = []) {
    for (let attempt = 0; attempt < 24; attempt++) {
      const r = minR + Math.random() * (maxR - minR);
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(2 * Math.random() - 1);
      const p = {
        x: r * Math.sin(phi) * Math.cos(theta),
        y: r * Math.cos(phi) * 0.6, // squashed: keep the field shallow
        z: r * Math.sin(phi) * Math.sin(theta),
      };
      const clear = avoid.every((a) => distance(p, a.position) > a.clear);
      if (clear) return p;
    }
    return { x: minR, y: 0, z: 0 };
  }

  spawnInitial(playerPos) {
    const cfg = this.config;
    const w = cfg.world;
    const avoid = this._avoidList(playerPos);

    for (let i = 0; i < cfg.salvage.count; i++) {
      const p = this._randomPoint(w.salvageMinRadius, w.salvageMaxRadius, avoid);
      const tier = rollCargoTier(Math.random, cfg);
      this.salvage.push(new Salvage(this.scene, p, 'cargo', cfg, tier));
    }
    for (let i = 0; i < cfg.fuelCanister.count; i++) {
      const p = this._randomPoint(w.salvageMinRadius, w.salvageMaxRadius, avoid);
      this.fuel.push(new Salvage(this.scene, p, 'fuel'));
    }
    // Hazards orbit their spawn center, so give them extra clearance from
    // the player's starting position.
    for (let i = 0; i < cfg.hazard.count; i++) {
      const center = this._randomPoint(
        w.salvageMinRadius, w.salvageMaxRadius,
        this._avoidList(playerPos, cfg.hazard.minFromPlayer)
      );
      const orbitRadius = cfg.hazard.orbitRadiusMin + Math.random() * (cfg.hazard.orbitRadiusMax - cfg.hazard.orbitRadiusMin);
      this.hazards.push(new Hazard(this.scene, center, orbitRadius, Math.random() * Math.PI * 2, cfg));
    }
    // Mines drift, so keep them clear of the player's starting position.
    for (let i = 0; i < cfg.mine.count; i++) {
      const p = this._randomPoint(
        w.salvageMinRadius, w.salvageMaxRadius,
        this._avoidList(playerPos, cfg.mine.triggerRadius)
      );
      this.mines.push(new Mine(this.scene, p, cfg));
    }
  }

  /**
   * Called when a salvage/fuel entity is collected.
   * Schedules a respawn after its delay so totals stay constant.
   */
  scheduleRespawn(type, readyAt) {
    this.respawnQueue.push({ type, readyAt });
  }

  update(dt, time, playerPos, surgeActive = false) {
    const cfg = this.config;
    const w = cfg.world;
    const bodies = this._bodies();

    // The market surge ends with the mission, so a restart mid-object resets it.
    if (!surgeActive) this.surgeActive = false;
    if (surgeActive && !this.surgeActive) {
      this.surgeActive = true;
      this._spawnSurgeHazards(playerPos);
    }
    for (const s of this.salvage) s.update(dt, bodies, w.bounds);
    for (const f of this.fuel) f.update(dt, bodies, w.bounds);
    for (const h of this.hazards) h.update(dt);
    for (const m of this.mines) m.update(dt, bodies, w.bounds);

    // Process respawn queue.
    const avoid = this._avoidList(playerPos);
    for (let i = this.respawnQueue.length - 1; i >= 0; i--) {
      const item = this.respawnQueue[i];
      if (time < item.readyAt) continue;
      const p = this._randomPoint(w.salvageMinRadius, w.salvageMaxRadius, avoid);
      if (item.type === 'salvage') {
        const tier = rollCargoTier(Math.random, cfg);
        this.salvage.push(new Salvage(this.scene, p, 'cargo', cfg, tier));
      } else if (item.type === 'fuel') {
        this.fuel.push(new Salvage(this.scene, p, 'fuel'));
      } else if (item.type === 'mine') {
        this.mines.push(new Mine(this.scene, p, cfg));
      }
      this.respawnQueue.splice(i, 1);
    }
  }

  /**
   * End-game pressure: when the surge window opens, drop a few extra hazards
   * (same orbit behavior as the regular field, so collision logic is unchanged).
   */
  _spawnSurgeHazards(playerPos) {
    const cfg = this.config;
    const w = cfg.world;
    for (let i = 0; i < cfg.surge.extraHazards; i++) {
      const center = this._randomPoint(
        w.salvageMinRadius, w.salvageMaxRadius,
        this._avoidList(playerPos, cfg.hazard.minFromPlayer)
      );
      const orbitRadius = cfg.hazard.orbitRadiusMin + Math.random() * (cfg.hazard.orbitRadiusMax - cfg.hazard.orbitRadiusMin);
      this.hazards.push(new Hazard(this.scene, center, orbitRadius, Math.random() * Math.PI * 2, cfg));
    }
  }

  /** Remove an entity from scene + arrays (memory-leak safe). */
  removeSalvage(entity) {
    const i = this.salvage.indexOf(entity);
    if (i >= 0) {
      this.salvage.splice(i, 1);
      entity.dispose(this.scene);
    }
  }

  removeFuel(entity) {
    const i = this.fuel.indexOf(entity);
    if (i >= 0) {
      this.fuel.splice(i, 1);
      entity.dispose(this.scene);
    }
  }

  removeMine(entity) {
    const i = this.mines.indexOf(entity);
    if (i >= 0) {
      this.mines.splice(i, 1);
      entity.dispose(this.scene);
    }
  }

  dispose() {
    for (const s of this.salvage) s.dispose(this.scene);
    for (const f of this.fuel) f.dispose(this.scene);
    for (const h of this.hazards) h.dispose(this.scene);
    for (const m of this.mines) m.dispose(this.scene);
    this.salvage = [];
    this.fuel = [];
    this.hazards = [];
    this.mines = [];
    this.respawnQueue = [];
  }
}

// Pure vector math utilities. All functions are side-effect free and operate
// on plain {x, y, z} objects so they are trivially testable without Three.js.

export function vec3(x = 0, y = 0, z = 0) {
  return { x, y, z };
}

export function clone(v) {
  return { x: v.x, y: v.y, z: v.z };
}

export function set(v, x, y, z) {
  v.x = x; v.y = y; v.z = z;
  return v;
}

export function add(a, b) {
  return { x: a.x + b.x, y: a.y + b.y, z: a.z + b.z };
}

export function sub(a, b) {
  return { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z };
}

export function scale(v, s) {
  return { x: v.x * s, y: v.y * s, z: v.z * s };
}

export function addScaled(a, b, s) {
  return { x: a.x + b.x * s, y: a.y + b.y * s, z: a.z + b.z * s };
}

export function dot(a, b) {
  return a.x * b.x + a.y * b.y + a.z * b.z;
}

export function cross(a, b) {
  return {
    x: a.y * b.z - a.z * b.y,
    y: a.z * b.x - a.x * b.z,
    z: a.x * b.y - a.y * b.x,
  };
}

export function length(v) {
  return Math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
}

export function lengthSq(v) {
  return v.x * v.x + v.y * v.y + v.z * v.z;
}

export function distance(a, b) {
  const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

export function distanceSq(a, b) {
  const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
  return dx * dx + dy * dy + dz * dz;
}

export function normalize(v) {
  const len = length(v);
  if (len < 1e-9) return vec3(0, 0, 0);
  return { x: v.x / len, y: v.y / len, z: v.z / len };
}

export function normalizeInto(v, out) {
  const len = length(v);
  if (len < 1e-9) { out.x = 0; out.y = 0; out.z = 0; return out; }
  out.x = v.x / len; out.y = v.y / len; out.z = v.z / len;
  return out;
}

export function lerp(a, b, t) {
  return a + (b - a) * t;
}

export function lerpVec3(a, b, t) {
  return {
    x: a.x + (b.x - a.x) * t,
    y: a.y + (b.y - a.y) * t,
    z: a.z + (b.z - a.z) * t,
  };
}

export function clamp(v, min, max) {
  return Math.min(max, Math.max(min, v));
}

export function clampLength(v, maxLen) {
  const len = length(v);
  if (len <= maxLen) return clone(v);
  const s = maxLen / len;
  return { x: v.x * s, y: v.y * s, z: v.z * s };
}

// Frame vectors derived from a yaw/pitch/roll orientation (arcade ship model).
// Yaw is rotation around +Y, pitch around local X, roll around local Z.
export function forwardFromOrientation(o) {
  const cy = Math.cos(o.yaw), sy = Math.sin(o.yaw);
  const cp = Math.cos(o.pitch), sp = Math.sin(o.pitch);
  return {
    x: -sy * cp,
    y: sp,
    z: -cy * cp,
  };
}

export function upFromOrientation(o) {
  const cy = Math.cos(o.yaw), sy = Math.sin(o.yaw);
  const cp = Math.cos(o.pitch), sp = Math.sin(o.pitch);
  const cr = Math.cos(o.roll), sr = Math.sin(o.roll);
  // right = (cy, 0, -sy); up = right × forward, then rolled around forward.
  const f = forwardFromOrientation(o);
  const right = { x: cy, y: 0, z: -sy };
  const base = cross(right, f); // unrolled up
  // Rodrigues rotation of `base` around axis `f` by o.roll
  const dotF = dot(base, f);
  const crossF = cross(f, base);
  return {
    x: base.x * cr + crossF.x * sr + f.x * dotF * (1 - cr),
    y: base.y * cr + crossF.y * sr + f.y * dotF * (1 - cr),
    z: base.z * cr + crossF.z * sr + f.z * dotF * (1 - cr),
  };
}

export function rightFromOrientation(o) {
  const cy = Math.cos(o.yaw), sy = Math.sin(o.yaw);
  return { x: cy, y: 0, z: -sy };
}

// Drifting salvage pods and fuel canisters. Salvage slowly drifts and
// rotates; both types glow so they read as pickups. Drift is contained by
// the world boundary and bounces off protected bodies (see driftEntity).

import * as THREE from 'three';
import { CONFIG } from '../config.js';
import { driftEntity } from '../systems/CollisionSystem.js';

export class Salvage {
  constructor(scene, position, kind = 'cargo', config = CONFIG, tier = 'standard') {
    this.kind = kind; // 'cargo' | 'fuel'
    this.tier = tier; // cargo tier: 'standard' | 'rare' | 'heavy'
    this.position = { ...position };
    const drift = config.salvage.driftSpeed * (config.salvage.tiers[tier]?.drift ?? 1);
    this.velocity = {
      x: (Math.random() - 0.5) * drift,
      y: (Math.random() - 0.5) * drift * 0.5,
      z: (Math.random() - 0.5) * drift,
    };
    this.radius = kind === 'fuel'
      ? config.fuelCanister.radius
      : (config.salvage.tiers[tier]?.radius ?? config.salvage.radius);
    this.rotSpeed = {
      x: (Math.random() - 0.5) * 1.6,
      y: (Math.random() - 0.5) * 1.6,
    };
    this.collected = false;

    this.group = new THREE.Group();
    this.group.position.copy(this.position);

    if (kind === 'cargo') {
      // Icosahedron pod with emissive core. Tier changes size (radius),
      // shell tint and core color so pods read at a glance.
      const tierStyle = {
        standard: { shell: 0x9fd8ff, core: 0x5dffa8 },
        rare:     { shell: 0xd8b4ff, core: 0xffd84d },
        heavy:    { shell: 0x8a9aa8, core: 0xff8844 },
      }[tier] ?? { shell: 0x9fd8ff, core: 0x5dffa8 };
      this.color = tierStyle.core;
      const shell = new THREE.Mesh(
        new THREE.IcosahedronGeometry(this.radius, 0),
        new THREE.MeshStandardMaterial({ color: tierStyle.shell, metalness: 0.8, roughness: 0.3, flatShading: true })
      );
      const core = new THREE.Mesh(
        new THREE.OctahedronGeometry(this.radius * 0.55),
        new THREE.MeshBasicMaterial({ color: tierStyle.core })
      );
      this.group.add(shell, core);
    } else {
      this.color = 0x5dffa8;
      // Fuel canister: cylinder + emissive band.
      const body = new THREE.Mesh(
        new THREE.CylinderGeometry(this.radius * 0.7, this.radius * 0.7, this.radius * 2, 10),
        new THREE.MeshStandardMaterial({ color: 0xffe08a, metalness: 0.5, roughness: 0.4 })
      );
      const band = new THREE.Mesh(
        new THREE.CylinderGeometry(this.radius * 0.72, this.radius * 0.72, this.radius * 0.5, 10),
        new THREE.MeshBasicMaterial({ color: 0x5dffa8 })
      );
      this.group.add(body, band);
    }

    scene.add(this.group);
  }

  /**
   * Advance drift. `bodies` are protected spheres (planets, station hub) the
   * pod bounces off; `bounds` is the world radius it reflects at.
   */
  update(dt, bodies = [], bounds = CONFIG.world.bounds) {
    if (this.collected) return;
    const next = driftEntity(this.position, this.velocity, dt, this.radius, bodies, bounds);
    this.position = next.position;
    this.velocity = next.velocity;
    this.group.position.copy(this.position);
    this.group.rotation.x += this.rotSpeed.x * dt;
    this.group.rotation.y += this.rotSpeed.y * dt;
  }

  dispose(scene) {
    scene.remove(this.group);
    this.group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
  }
}

