import { describe, it, expect } from 'vitest';
import {
  spheresCollide, pointInSphere, isBelowSpeed,
  pushOutOfSphere, bounceVelocity, driftEntity,
} from '../src/systems/CollisionSystem.js';

describe('collision system', () => {
  it('spheresCollide detects overlap and separation', () => {
    expect(spheresCollide({ x: 0, y: 0, z: 0 }, 2, { x: 3, y: 0, z: 0 }, 2)).toBe(true);
    expect(spheresCollide({ x: 0, y: 0, z: 0 }, 2, { x: 5, y: 0, z: 0 }, 2)).toBe(false);
  });

  it('pointInSphere bounds the docking zone', () => {
    expect(pointInSphere({ x: 5, y: 0, z: 0 }, { x: 0, y: 0, z: 0 }, 10)).toBe(true);
    expect(pointInSphere({ x: 15, y: 0, z: 0 }, { x: 0, y: 0, z: 0 }, 10)).toBe(false);
  });

  it('isBelowSpeed compares squared speeds', () => {
    expect(isBelowSpeed({ x: 10, y: 0, z: 0 }, 10)).toBe(true);
    expect(isBelowSpeed({ x: 20, y: 0, z: 0 }, 10)).toBe(false);
  });

  it('pushOutOfSphere places the ship on the surface', () => {
    const p = pushOutOfSphere({ x: 2, y: 0, z: 0 }, { x: 0, y: 0, z: 0 }, 5);
    const d = Math.sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
    expect(d).toBeCloseTo(5);
    // Outside the sphere is unchanged.
    const far = pushOutOfSphere({ x: 9, y: 0, z: 0 }, { x: 0, y: 0, z: 0 }, 5);
    expect(far).toEqual({ x: 9, y: 0, z: 0 });
  });

  it('bounceVelocity removes the normal component and damps', () => {
    const v = bounceVelocity({ x: 0, y: -10, z: 0 }, { x: 0, y: 1, z: 0 }, 0.5);
    expect(v.y).toBeGreaterThan(0); // reflected
    expect(Math.abs(v.y)).toBeLessThan(10); // damped
    // Moving away from the surface is untouched.
    const away = bounceVelocity({ x: 0, y: 5, z: 0 }, { x: 0, y: 1, z: 0 });
    expect(away).toEqual({ x: 0, y: 5, z: 0 });
  });

  describe('driftEntity', () => {
    const planet = { position: { x: 0, y: 0, z: 0 }, radius: 10 };

    it('bounces a pod off a protected body and keeps it outside', () => {
      // Start just outside the planet, moving straight at its center fast
      // enough to reach the surface within the step.
      const { position, velocity } = driftEntity(
        { x: 14, y: 0, z: 0 }, { x: -3, y: 0, z: 0 }, 1, 2, [planet], 400
      );
      const d = Math.sqrt(position.x ** 2 + position.y ** 2 + position.z ** 2);
      expect(d).toBeCloseTo(12, 5); // resting on the surface (10 + 2)
      // Velocity now points away from the planet.
      expect(velocity.x * position.x).toBeGreaterThan(0);
    });

    it('reflects pods at the world boundary and keeps them inside', () => {
      let pos = { x: 390, y: 0, z: 0 };
      let vel = { x: 5, y: 0, z: 0 };
      for (let i = 0; i < 200; i++) {
        const next = driftEntity(pos, vel, 0.016, 2, [], 400);
        pos = next.position;
        vel = next.velocity;
      }
      const d = Math.sqrt(pos.x ** 2 + pos.y ** 2 + pos.z ** 2);
      expect(d).toBeLessThanOrEqual(400 + 1e-6);
    });

    it('never tunnels through a body even with a large step', () => {
      // A 60-unit step toward the planet must not land inside it.
      const { position } = driftEntity(
        { x: 13, y: 0, z: 0 }, { x: -12, y: 0, z: 0 }, 5, 2, [planet], 400
      );
      const d = Math.sqrt(position.x ** 2 + position.y ** 2 + position.z ** 2);
      expect(d).toBeGreaterThanOrEqual(12 - 1e-6);
    });

    it('preserves drift speed magnitude (no energy gain/loss)', () => {
      let pos = { x: 100, y: 20, z: -60 };
      let vel = { x: 1.2, y: -0.8, z: 0.4 };
      for (let i = 0; i < 100; i++) {
        const next = driftEntity(pos, vel, 0.016, 2, [planet], 400);
        pos = next.position;
        vel = next.velocity;
      }
      const before = Math.sqrt(1.2 ** 2 + 0.8 ** 2 + 0.4 ** 2);
      const after = Math.sqrt(vel.x ** 2 + vel.y ** 2 + vel.z ** 2);
      expect(after).toBeCloseTo(before, 5);
    });

    it('passes through untouched when nothing is nearby', () => {
      const { position, velocity } = driftEntity(
        { x: 100, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }, 0.5, 2, [planet], 400
      );
      expect(position.x).toBeCloseTo(100.5);
      expect(velocity).toEqual({ x: 1, y: 0, z: 0 });
    });
  });
});

