// Central game state. Plain data + deterministic update rules.
// Rendering never lives here; this module can be unit-tested headlessly.

import { CONFIG } from '../config.js';
import { pointInSphere } from '../systems/CollisionSystem.js';
import { extraFuelBurn, holdValue } from './Cargo.js';

export const MISSION_STATE = {
  START: 'start',
  PLAYING: 'playing',
  SUCCESS: 'success',
  FAILURE: 'failure',
};

export function createGameState(config = CONFIG) {
  return {
    state: MISSION_STATE.START,
    time: 0,                 // elapsed mission seconds
    credits: 0,
    cargoItems: [],          // salvage carried: [{ tier }, ...]
    fuel: config.ship.maxFuel,
    hull: config.ship.maxHull,
    deliveries: 0,
    salvageCollected: 0,
    damageTaken: 0,
    topSpeed: 0,             // peak speed reached this mission (u/s)
    combo: 1,                // current delivery multiplier (see comboMultiplier)
    comboDeliveries: 0,      // consecutive deliveries since the last damage
    bestCombo: 1,            // highest multiplier reached this mission
    surgeEarnings: 0,        // extra credits earned from the market surge
    invulnerability: 0,      // seconds of post-hit grace remaining
    dockCooldown: 0,
    inDockZone: false,
    config,                  // active (difficulty-applied) config
  };
}

/**
 * Consume fuel for thrust. Heavy cargo in the hold raises the burn rate
 * (see Cargo.extraFuelBurn). Returns the fuel actually burned (0 when empty).
 * Mutates state.fuel.
 */
export function consumeFuel(state, dt, boosting = false) {
  const c = state.config.ship;
  const burn = c.fuelBurn + (boosting ? c.boostFuelBurn : 0) + extraFuelBurn(state.cargoItems, state.config);
  const wanted = burn * dt;
  const burned = Math.min(state.fuel, wanted);
  state.fuel = Math.max(0, state.fuel - burned);
  return burned;
}

/**
 * Apply a knockback impulse (e.g. from a proximity mine). `direction` is a
 * unit-ish vector; the resulting speed is capped at the boost ceiling so a
 * mine can never launch the ship out of the world.
 * Mutates state — callers must have a velocity object; this returns the new
 * velocity vector, so assign it back (ship.velocity = applyImpulse(...)).
 */
export function applyImpulse(state, velocity, direction, strength) {
  const cap = state.config.ship.boostMaxSpeed * 1.25;
  const v = {
    x: velocity.x + direction.x * strength,
    y: velocity.y + direction.y * strength,
    z: velocity.z + direction.z * strength,
  };
  const len = Math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
  if (len > cap) {
    const s = cap / len;
    return { x: v.x * s, y: v.y * s, z: v.z * s };
  }
  return v;
}

/**
 * Multiplier for the given number of consecutive (undamaged) deliveries:
 * the highest configured step whose threshold is met. Pure — reads only the
 * config's combo.steps table.
 */
export function comboMultiplier(deliveries, config) {
  const steps = config.combo.steps;
  let mult = steps[0].multiplier;
  for (const s of steps) {
    if (deliveries >= s.deliveries) mult = s.multiplier;
  }
  return mult;
}

/**
 * Feed a gameplay event into the delivery combo.
 *   { type: 'delivery', count } — count units delivered in one dock;
 *   { type: 'damage' }   — the combo resets to ×1.
 * Mutates state.combo / comboDeliveries / bestCombo; returns the new combo.
 */
export function updateCombo(state, event) {
  if (event.type === 'delivery') {
    state.comboDeliveries += event.count;
    state.combo = comboMultiplier(state.comboDeliveries, state.config);
    state.bestCombo = Math.max(state.bestCombo, state.combo);
  } else if (event.type === 'damage') {
    state.comboDeliveries = 0;
    state.combo = 1;
  }
  return state.combo;
}

/**
 * Market-surge payout multiplier: 1 normally, the configured bonus while
 * `timeRemaining` is inside the surge window (the final stretch).
 */
export function surgeMultiplier(timeRemaining, config) {
  if (timeRemaining <= config.surge.window) return config.surge.salvageValueMultiplier;
  return 1;
}

/**
 * Apply hull damage, respecting the invulnerability window.
 * Returns true if damage was applied.
 */
export function applyDamage(state, amount) {
  if (state.invulnerability > 0) return false;
  state.hull = Math.max(0, state.hull - amount);
  state.damageTaken += amount;
  state.invulnerability = state.config.ship.invulnerability;
  updateCombo(state, { type: 'damage' });
  if (state.hull <= 0) {
    state.hull = 0;
    state.state = MISSION_STATE.FAILURE;
  }
  return true;
}

/**
 * Dock logic: inside the zone and slow enough -> deliver cargo.
 * Inside the zone but too fast -> take damage.
 * Returns 'docked' | 'tooFast' | 'none'.
 */
export function updateDocking(state, position, velocity, station, dt) {
  const cfg = state.config;
  const s = cfg.station;
  state.dockCooldown = Math.max(0, state.dockCooldown - dt);

  const inZone = pointInSphere(position, station.position, s.dockRadius);
  state.inDockZone = inZone;
  if (!inZone) return 'none';

  const slow = velocity.x * velocity.x + velocity.y * velocity.y + velocity.z * velocity.z <= s.dockSpeedLimit * s.dockSpeedLimit;
  if (!slow) {
    if (state.dockCooldown <= 0) {
      applyDamage(state, s.fastDockDamage);
      state.dockCooldown = s.dockCooldown;
    }
    return 'tooFast';
  }

  if (state.dockCooldown > 0) return 'none';
  if (state.cargoItems.length > 0) {
    // Payout = hold value × combo × surge (surge only in the final window).
    const base = holdValue(state.cargoItems, cfg) * state.combo;
    const surge = surgeMultiplier(cfg.mission.duration - state.time, cfg);
    const payout = Math.round(base * surge);
    state.surgeEarnings += payout - Math.round(base);
    state.credits += payout;
    const count = state.cargoItems.length;
    state.deliveries += count;
    state.cargoItems = [];
    state.dockCooldown = s.dockCooldown;
    updateCombo(state, { type: 'delivery', count });
    if (state.credits >= cfg.mission.targetCredits) {
      state.state = MISSION_STATE.SUCCESS;
    }
    return 'docked';
  }
  return 'none';
}

/**
 * Advance timers and check win/lose conditions.
 * Returns the new mission state (also written to state.state).
 */
export function tickMission(state, dt, topSpeed = null) {
  if (state.state !== MISSION_STATE.PLAYING) return state.state;

  state.time += dt;
  state.invulnerability = Math.max(0, state.invulnerability - dt);
  if (topSpeed != null) state.topSpeed = Math.max(state.topSpeed, topSpeed);

  if (state.credits >= state.config.mission.targetCredits) {
    state.state = MISSION_STATE.SUCCESS;
  } else if (state.time >= state.config.mission.duration) {
    state.state = MISSION_STATE.FAILURE;
  }
  return state.state;
}

export function missionTimeRemaining(state) {
  return Math.max(0, state.config.mission.duration - state.time);
}

export function formatTime(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${m}:${r.toString().padStart(2, '0')}`;
}

/**
 * Soft world boundary: acceleration pushing the player back toward the
 * center when they cross the boundary radius.
 */
export function boundaryCorrection(position, bounds = CONFIG.world.bounds) {
  const d = Math.sqrt(position.x * position.x + position.y * position.y + position.z * position.z);
  if (d <= bounds) return { x: 0, y: 0, z: 0 };
  const excess = d - bounds;
  const k = 0.8; // gentle spring
  const s = (k * excess) / d;
  return { x: -position.x * s, y: -position.y * s, z: -position.z * s };
}

// DOM-based HUD. Reads a plain status object each frame; no game logic.

import { CONFIG } from '../config.js';
import { formatTime, missionTimeRemaining } from '../game/GameState.js';
import { radarPositions, screenDirection } from '../utils/radar.js';

const RADAR_RANGE = 130; // world units shown at the radar edge

const BLIP_COLORS = {
  salvage: '#5dffa8',
  fuel: '#ffe08a',
  hazard: '#ff8a5d',
  mine: '#ff4433',
  station: '#58c8ff',
};

export class HUD {
  constructor() {
    this.el = {
      hud: document.getElementById('hud'),
      timer: document.getElementById('hud-timer'),
      credits: document.getElementById('hud-credits'),
      cargo: document.getElementById('hud-cargo'),
      fuel: document.getElementById('hud-fuel'),
      fuelText: document.getElementById('hud-fuel-text'),
      hull: document.getElementById('hud-hull'),
      hullText: document.getElementById('hud-hull-text'),
      hint: document.getElementById('hud-hint'),
      overlayStart: document.getElementById('overlay-start'),
      overlayEnd: document.getElementById('overlay-end'),
      overlayPause: document.getElementById('overlay-pause'),
      difficultyRow: document.getElementById('difficulty-row'),
      endTitle: document.getElementById('end-title'),
      endMessage: document.getElementById('end-message'),
      endStats: document.getElementById('end-stats'),
      radar: document.getElementById('hud-radar'),
      combo: document.getElementById('hud-combo'),
      comboValue: document.getElementById('hud-combo-value'),
      surge: document.getElementById('hud-surge'),
      stationIndicator: document.getElementById('hud-station-indicator'),
      stationArrow: document.getElementById('hud-station-arrow'),
      stationDist: document.getElementById('hud-station-dist'),
      damageFlash: document.getElementById('damage-flash'),
    };
    this._flashTimer = null;
  }

  show() {
    this.el.hud.classList.remove('hidden');
  }

  hide() {
    this.el.hud.classList.add('hidden');
  }

  /**
   * state: the live GameState object.
   * hint: optional contextual hint string.
   */
  update(state, hint, radarData = null, flags = {}) {
    const cfg = state.config || CONFIG;
    const remaining = missionTimeRemaining(state);
    this.el.hud.classList.toggle('paused', !!flags.paused);

    // Combo readout: shown only once the multiplier is above ×1.
    const combo = flags.combo ?? state.combo ?? 1;
    this.el.combo.classList.toggle('hidden', combo <= 1);
    this.el.comboValue.textContent = `×${combo}`;
    this.el.surge.classList.toggle('hidden', !flags.surge);
    this.el.timer.textContent = formatTime(remaining);
    this.el.timer.classList.toggle('low', remaining < 30);
    this.el.credits.textContent = `${state.credits} / ${cfg.mission.targetCredits}`;
    this.el.cargo.textContent = `${state.cargoItems.length} / ${cfg.salvage.cargoCapacity}`;

    const fuelPct = (state.fuel / CONFIG.ship.maxFuel) * 100;
    this.el.fuel.style.width = `${fuelPct}%`;
    this.el.fuelText.textContent = Math.ceil(state.fuel);
    this.el.fuel.classList.toggle('low', fuelPct < 25);
    this.el.fuelText.classList.toggle('low', fuelPct < 25);

    const hullPct = (state.hull / CONFIG.ship.maxHull) * 100;
    this.el.hull.style.width = `${hullPct}%`;
    this.el.hullText.textContent = Math.ceil(state.hull);
    this.el.hull.classList.toggle('low', hullPct < 30);
    this.el.hullText.classList.toggle('low', hullPct < 30);

    if (hint !== undefined) {
      this.el.hint.textContent = hint;
      this.el.hint.classList.toggle('low', fuelPct < 25 || hullPct < 30);
    }
    if (radarData) this._drawRadar(radarData);
  }

  /**
   * radarData: { shipPos, orientation, entities, station: {position, visible}, camera }
   * entities: [{ position, kind }] — station is drawn separately (always shown).
   */
  _drawRadar({ shipPos, orientation, entities, station, camera }) {
    const canvas = this.el.radar;
    const ctx = canvas.getContext('2d');
    const size = canvas.width;
    const c = size / 2;
    const scale = (c - 8) / RADAR_RANGE;
    ctx.clearRect(0, 0, size, size);

    // Range rings.
    ctx.strokeStyle = 'rgba(88, 200, 255, 0.25)';
    ctx.lineWidth = 1;
    for (const r of [0.33, 0.66, 1]) {
      ctx.beginPath();
      ctx.arc(c, c, (c - 8) * r, 0, Math.PI * 2);
      ctx.stroke();
    }

    const blips = radarPositions(shipPos, orientation, [...entities, { position: station.position, kind: 'station' }], RADAR_RANGE);
    for (const b of blips) {
      const px = c + b.x * scale;
      const py = c - b.y * scale; // forward = up
      const color = BLIP_COLORS[b.kind] ?? '#ffffff';
      ctx.globalAlpha = b.offScreen ? 0.45 : 1;
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(px, py, b.kind === 'station' ? 4 : 2.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Ship: heading triangle at center.
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.moveTo(c, c - 6);
    ctx.lineTo(c - 4, c + 4);
    ctx.lineTo(c + 4, c + 4);
    ctx.closePath();
    ctx.fill();

    // Station approach indicator (off-screen arrow + distance).
    if (camera && station) {
      const d = screenDirection(camera.position, camera.forward, camera.right, camera.up, station.position);
      const ind = this.el.stationIndicator;
      if (d.distance > 60) {
        ind.classList.remove('hidden');
        // CSS ▲ points up; rotate it toward the screen-space direction
        // (screen y is up here, CSS y is down — hence the negation).
        const rad = Math.atan2(-d.y, d.x) + Math.PI / 2;
        this.el.stationArrow.style.transform = `rotate(${rad}rad)`;
        this.el.stationDist.textContent = Math.round(d.distance);
      } else {
        ind.classList.add('hidden');
      }
    }
  }

  flashDamage() {
    const el = this.el.damageFlash;
    if (!el) return;
    el.classList.add('active');
    if (this._flashTimer) clearTimeout(this._flashTimer);
    this._flashTimer = setTimeout(() => el.classList.remove('active'), 120);
  }

  showStart(difficulty = 'normal') {
    this.el.overlayStart.classList.remove('hidden');
    this.el.overlayEnd.classList.add('hidden');
    const wrap = this.el.difficultyRow;
    if (wrap) {
      for (const btn of wrap.querySelectorAll('button[data-difficulty]')) {
        btn.classList.toggle('selected', btn.dataset.difficulty === difficulty);
      }
    }
  }

  hideStart() {
    this.el.overlayStart.classList.add('hidden');
  }

  /** Show or hide the pause overlay (called by Game._setPaused). */
  showPause(visible) {
    this.el.overlayPause.classList.toggle('hidden', !visible);
  }

  showEnd(state, { stats, newCredits = false, newTime = false } = {}) {
    this.el.overlayEnd.classList.remove('hidden');
    const won = state.state === 'success';
    this.el.endTitle.textContent = won ? 'MISSION COMPLETE' : 'MISSION FAILED';
    this.el.endTitle.className = `title ${won ? 'success' : 'failure'}`;
    this.el.endMessage.textContent = won
      ? 'Cargo delivered. The station ledger thanks you.'
      : state.hull <= 0
        ? 'Hull integrity lost. The void claims another hauler.'
        : 'Time expired before the credit target was met.';
    const s = stats || {
      difficulty: 'normal',
      credits: state.credits,
      deliveries: state.deliveries,
      salvageCollected: state.salvageCollected,
      damageTaken: Math.round(state.damageTaken),
      topSpeed: Math.round((state.topSpeed || 0) * 10) / 10,
      timeUsed: formatTime(state.time),
    };
    const callout = newCredits
      ? 'NEW RECORD — BEST CREDITS'
      : newTime
        ? 'NEW RECORD — FASTEST WIN'
        : '';
    this.el.endStats.innerHTML = `
      <div class="stat"><span class="hud-label">DIFFICULTY</span><span class="hud-value">${s.difficulty}</span></div>
      <div class="stat"><span class="hud-label">CREDITS</span><span class="hud-value">${s.credits}</span></div>
      <div class="stat"><span class="hud-label">DELIVERIES</span><span class="hud-value">${s.deliveries}</span></div>
      <div class="stat"><span class="hud-label">SALVAGE COLLECTED</span><span class="hud-value">${s.salvageCollected}</span></div>
      <div class="stat"><span class="hud-label">DAMAGE TAKEN</span><span class="hud-value">${s.damageTaken}</span></div>
      <div class="stat"><span class="hud-label">TOP SPEED</span><span class="hud-value">${s.topSpeed}</span></div>
      <div class="stat"><span class="hud-label">TIME USED</span><span class="hud-value">${s.timeUsed}</span></div>
      ${s.bestCombo != null ? `<div class="stat"><span class="hud-label">BEST COMBO</span><span class="hud-value">×${s.bestCombo}</span></div>` : ''}
      ${s.surgeEarnings != null ? `<div class="stat"><span class="hud-label">SURGE EARNINGS</span><span class="hud-value">+${s.surgeEarnings}</span></div>` : ''}
      ${callout ? `<div class="stat record">${callout}</div>` : ''}
    `;
  }

  hideEnd() {
    this.el.overlayEnd.classList.add('hidden');
  }
}

